#include "eventControlMock_eventControlMockThread.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void eventControlMock_eventControlMockThread_initialize(void);
void eventControlMock_eventControlMockThread_notify(microkit_channel channel);
void eventControlMock_eventControlMockThread_timeTriggered(void);

volatile sb_queue_bool_1_t *manualActuatorInput1_queue_1;
volatile sb_queue_bool_1_t *manualActuatorInput2_queue_1;

#define PORT_FROM_MON 0

bool put_manualActuatorInput1(const bool *data) {
  sb_queue_bool_1_enqueue((sb_queue_bool_1_t *) manualActuatorInput1_queue_1, (bool *) data);

  return true;
}

bool put_manualActuatorInput2(const bool *data) {
  sb_queue_bool_1_enqueue((sb_queue_bool_1_t *) manualActuatorInput2_queue_1, (bool *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_bool_1_init((sb_queue_bool_1_t *) manualActuatorInput1_queue_1);

  sb_queue_bool_1_init((sb_queue_bool_1_t *) manualActuatorInput2_queue_1);

  eventControlMock_eventControlMockThread_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      eventControlMock_eventControlMockThread_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      eventControlMock_eventControlMockThread_notify(channel);
  }
}
